WFJ.Data.add("book", {
  ["551a95ea2a7969ac"] = { "Mentre la titanica battaglia infuriava attorno alla capitale di Azshara, la regina, preda delle sue illusioni, attendeva con ansia l'arrivo di Sargeras. Il signore della Legione si preparava ad attraversare il ⟦Well of Eternity=Pozzo dell'Eternità⟧ per entrare nel mondo devastato. Mentre la sua ombra smisurata si avvicinava sempre più alla superficie del Pozzo, Azshara radunò i più potenti tra i suoi seguaci ⟦Highborne=Alti Nobili⟧. Solo unendo le loro magie in un unico incantesimo concentrato avrebbero potuto creare un varco abbastanza grande da far entrare Sargeras.", "." },
  ["554470d8390b4a93"] = { "<HTML>\n<BODY>\n<H1>Registro di arruolamento dell'⟦Horde=Orda⟧</H1>\n<BR></BR>\n<P>Questa persona ha compiuto incredibili imprese di forza e abilità nel nome dell'⟦Horde=Orda⟧. Deve essere assegnata immediatamente al lavoro al ⟦Crossroads=Crocevia⟧.</P>\n<BR></BR>\n<BR></BR>\n<P>Distinti saluti:</P>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<BR></BR>\n<P>Per me va bene.<BR></BR>\n- Takrin Pathseeker</P>\n</BODY>\n</HTML>", "." },
  ["556538a973765e47"] = { "Una Gemma Kor - Da quel che mi hanno raccontato, alcuni incantatori usano queste gemme per conservare energia per le loro magie, rendendole ancora più letali. Un elfo della notte che ho aiutato una volta, Thundris Windweaver, potrà dirti di più, dato che parlerai a nome mio. Credo che l'energia accumulata in una di queste gemme si possa usare nella creazione della tua arma.\n\nL'ultima volta che ci siamo parlati, Thundris era ad Auberdine, una cittadina nel cuore di ⟦Darkshore=Rivafosca⟧, la foresta corrotta che costeggia il litorale all'ombra della patria degli elfi della notte.", "." },
  ["55ed1edd712360a4"] = { "Solo pochi mesi dopo il completamento di Guardiafatua, le energie del Portale Oscuro si addensarono e aprirono un nuovo varco verso Draenor. I clan di orchi rimasti, sotto la guida dell'anziano sciamano Ner'zhul, si lanciarono di nuovo su Azeroth. Decisi a rubare una serie di manufatti magici che avrebbero accresciuto il potere di Ner'zhul, gli orchi intendevano aprire nuovi portali su Draenor che avrebbero permesso loro di fuggire per sempre dal loro rosso mondo condannato.", "." },
})
